SELECT "SalariesFrance_6"."ROME" AS "ROME",   "SalariesFrance_6"."ROME_LIB" AS "ROME_LIB",   MIN("SalariesFrance_6"."CODGEO_PRINCIPAL") AS "min_CODGEO_PRINCIPAL_nk",   SUM("SalariesFrance_6"."EMPSAL_NP1") AS "sum_EMPSAL_NP1_ok" FROM "SalariesFrance_6" GROUP BY "SalariesFrance_6"."ROME",   "SalariesFrance_6"."ROME_LIB" HAVING (SUM("SalariesFrance_6"."EMPSAL_NP1") >= cast('0' as double));
